import {migrationView,registerView,assessmentRegister,checklistRegister,sourceButton} from './records.mjs';
import {STATUSES,OUTCOMES,BATCH_STATUSES,today,addDays,attendanceStats,batchStats,scores,summary,checklist,cairoTime,minutesLate,wasLate,assessedRows,averageScore,assessmentFor,checklistFor} from './core.mjs';
import {e,icon,btn,iconBtn,avatar,initials,ring,progress,badge,fmt,dateLabel,empty,stat,lineChart,donut,option} from './ui.mjs';
export const NAV=[['dashboard','Overview','grid'],['batches','Batches','cap'],['trainees','Trainees','users'],['attendance','Daily attendance','calendar'],['summaries','10-day checklist','checklist'],['assessments','Assessments','award'],['companies','Companies','building'],['analytics','Analytics & reports','chart'],['register','Attendance records','list'],['migration','Notion import & review','database']];
export function scoped(ctx){const d=ctx.store.data,trainees=d.trainees.filter(t=>(!ctx.batchId||t.batch_id===ctx.batchId)&&(!ctx.companyId||t.company_id===ctx.companyId));const ids=new Set(trainees.map(t=>t.id));const match=r=>(!ctx.batchId||r.batch_id===ctx.batchId)&&(!ctx.companyId||ids.has(r.trainee_id)||r.company_id===ctx.companyId);return {...d,trainees,batches:d.batches.filter(b=>(!ctx.batchId||b.id===ctx.batchId)&&(!ctx.companyId||trainees.some(t=>t.batch_id===b.id))),daily_attendance:d.daily_attendance.filter(match),attendance_10day:d.attendance_10day.filter(match),assessments:d.assessments.filter(match)};}
const company=(ctx,id)=>ctx.store.data.companies.find(c=>c.id===id)?.name||'Company not recorded';
const batch=(ctx,id)=>ctx.store.data.batches.find(b=>b.id===id);
function person(ctx,t,sub='company'){if(!t)return '<div class="person"><div class="person-info"><strong>Unassigned source record</strong><small>No person was invented</small></div></div>';return `<div class="person">${avatar(t.trainee_name)}<div class="person-info"><button data-action="profile" data-id="${t.id}">${e(t.trainee_name)}</button><small>${e(sub==='company'?company(ctx,t.company_id):t.source_meta?.membership_basis==='record_relation'?'Record-linked enrollment':t.source_meta?.membership_basis==='named_record'?'Named in source records':t.job_title||'Trainee')}</small></div></div>`;}
function companyLogo(name){return `<span class="company-logo ${name==='RED'?'brand-red':''}" aria-hidden="true">${e(name==='RED'?'RED':name.length<5?name.toUpperCase():initials(name))}</span>`;}
export function scopeBar(ctx,{requiredBatch=false}={}){return `<div class="scope-bar"><span class="scope-label">Workspace scope</span><select aria-label="Filter by batch" data-field="batchId">${requiredBatch?'':option('','All batches',ctx.batchId)}${ctx.store.data.batches.map(b=>option(b.id,b.batch_name,ctx.batchId)).join('')}</select><select aria-label="Filter by company" data-field="companyId">${option('','All companies',ctx.companyId)}${[...ctx.store.data.companies].sort((a,b)=>a.name.localeCompare(b.name)).map(c=>option(c.id,c.name,ctx.companyId)).join('')}</select>${ctx.batchId||ctx.companyId?btn('Reset filters','reset-filters','ghost','x'):''}<span class="scope-note">${icon('clock',12)} All times in Cairo</span></div>`;}
export function heading(title,description,actions='',eyebrow='INTERNAL WORKSPACE'){return `<header class="page-header"><div><span class="eyebrow">${e(eyebrow)}</span><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="page-actions">${actions}</div></header>`;}
function searchInput(ctx,placeholder='Search trainees...'){return `<div class="search-input">${icon('search',16)}<input id="view-search" data-field="search" type="search" placeholder="${e(placeholder)}" value="${e(ctx.search)}" aria-label="${e(placeholder)}"></div>`;}
function pageRows(ctx,rows,size=15){const pages=Math.max(1,Math.ceil(rows.length/size));ctx.page=Math.min(ctx.page,pages);return {rows:rows.slice((ctx.page-1)*size,ctx.page*size),count:rows.length,pages,size};}
function pagination(ctx,p){return `<div class="table-footer"><span>${p.count?`${(ctx.page-1)*p.size+1}-${Math.min(ctx.page*p.size,p.count)} of ${p.count} records`:'0 records'}</span><div class="pagination">${iconBtn('chevron','prev-page','Previous page',`style="transform:rotate(180deg)" ${ctx.page===1?'disabled':''}`)}<span>Page ${ctx.page} of ${p.pages}</span>${iconBtn('chevron','next-page','Next page',ctx.page>=p.pages?'disabled':'')}</div></div>`;}
function findTrainees(ctx,d){const q=ctx.search.toLowerCase().trim();return d.trainees.filter(t=>!q||[t.trainee_name,company(ctx,t.company_id),t.email,t.job_title].join(' ').toLowerCase().includes(q)).sort((a,b)=>ctx.sort==='company'?company(ctx,a.company_id).localeCompare(company(ctx,b.company_id)):a.trainee_name.localeCompare(b.trainee_name));}
function outcomeItems(assessments){const colors=['var(--red)','var(--orange)','var(--amber)','var(--purple)','var(--blue)','var(--green)'];return [...OUTCOMES].reverse().map(label=>({label,value:assessments.filter(a=>a.assessment_outcome===label).length,color:colors[OUTCOMES.indexOf(label)]}));}
function trend(d,days){return Array.from({length:days},(_,i)=>{const date=addDays(today(),i-days+1);return {date,...attendanceStats(d.daily_attendance.filter(r=>r.date===date))};});}
function companyStats(ctx,d){return ctx.store.data.companies.filter(c=>!ctx.companyId||c.id===ctx.companyId).map(c=>{const trainees=d.trainees.filter(t=>t.company_id===c.id),ids=new Set(trainees.map(t=>t.id)),a=assessedRows(d.assessments.filter(a=>ids.has(a.trainee_id)));return {...c,trainees:trainees.length,batches:new Set(trainees.map(t=>t.batch_id)).size,average:a.length?a.reduce((s,a)=>s+scores(a).overall,0)/a.length:null,assessed:a.length,attendance:attendanceStats(d.daily_attendance.filter(r=>ids.has(r.trainee_id)))};});}
function batchMini(ctx,b,d){const stats=batchStats(d,b.id),people=d.trainees.filter(t=>t.batch_id===b.id);return `<div class="batch-mini" role="button" tabindex="0" data-action="batch-detail" data-id="${b.id}" aria-label="Open ${e(b.batch_name)}"><div class="batch-mini-title"><span class="batch-mini-symbol">${icon('cap',18)}</span><div><strong>${e(b.batch_name)}</strong><small>${dateLabel(b.start_date)} - ${dateLabel(b.end_date)} &middot; ${people.length} trainees</small></div>${badge(b.status)}</div><div class="batch-mini-bottom"><div class="avatar-stack">${people.slice(0,3).map(t=>avatar(t.trainee_name,true)).join('')}${people.length>3?`<span class="avatar-count">+${people.length-3}</span>`:''}</div><span>${stats.completion===null?'No checklist':fmt(stats.completion)+'% checklist'}</span>${progress(stats.completion,100,b.status==='Completed'?'green':'red')}</div></div>`;}
export function dashboard(ctx){if(!ctx.store.data.trainees.length)return gettingStarted(ctx);const d=scoped(ctx),stats=attendanceStats(d.daily_attendance.filter(r=>r.date===today())),active=d.batches.filter(b=>b.status==='Active'),allAssess=assessedRows(d.assessments),avg=averageScore(allAssess);const high=allAssess.filter(a=>['Aced','Excellent'].includes(a.assessment_outcome)).length;const scheduled=d.trainees.filter(t=>batch(ctx,t.batch_id)?.session_dates.includes(today())).length;const unrecorded=Math.max(0,scheduled-d.daily_attendance.filter(r=>r.date===today()).length);const companies=companyStats(ctx,d).sort((a,b)=>b.trainees-a.trainees);const recent=[...d.daily_attendance].filter(r=>r.arrival_time).sort((a,b)=>b.arrival_time.localeCompare(a.arrival_time)).slice(0,3);const write=ctx.store.canWrite();const planning=d.batches.filter(b=>b.status==='Planning').length;
 return heading('Overview','Current operational view.',`${btn('Export report','export','secondary','download')}${write?btn('New batch','new-batch','primary','plus'):''}`,'TRAINING OPERATIONS')+scopeBar(ctx)+`
 <div class="hero-row"><section class="hero"><div class="hero-copy"><div class="hero-tag"><i></i> INTERNAL OPERATIONS</div><h2>Training operations<br>in one place.</h2><p>Manage attendance, rosters and assessments.<br>For authorized company staff only.</p><button class="text-link" data-action="go-attendance">Open today's attendance ${icon('arrow',15)}</button></div><div class="academy-art" aria-hidden="true"><div class="art-platform"></div><span class="art-cross one">+</span><span class="art-cross two">+</span><span class="art-caption">INTERNAL RECORDS</span></div></section><section class="today-card"><span class="eyebrow">TODAY'S ATTENDANCE ${icon('calendar',14)}</span><h3>${dateLabel(today(),{weekday:'long'})}</h3><div class="today-date">${dateLabel(today(),{month:'long',day:'numeric',year:'numeric'})}</div><div class="today-count"><div><strong>${stats.present}</strong><span>trainees marked present</span></div>${ring(stats.rate||0,47,'green')}</div><button class="text-link" data-action="go-attendance">${unrecorded?unrecorded+' awaiting a status':'View the daily register'} ${icon('arrow',14)}</button></section></div>
 <div class="stats-grid">${stat('Active batches',active.length,'cap',`<span class="mini-pill">${planning} planning</span><span>${d.batches.length} batches in view</span>`)}${stat('Enrolled trainees',d.trainees.length,'users',`<span>${new Set(d.trainees.map(t=>t.company_id).filter(Boolean)).size} companies represented</span>`)}${stat('Today\'s attendance',stats.rate===null?'\u2014':fmt(stats.rate,1)+'%','calendar',`<span class="mini-pill">${stats.present} present</span><span>${stats.absent} absent</span>`)}${stat('Average assessment',avg===null?'\u2014':fmt(avg,1)+'%','award',`<span class="mini-pill">${high} high scores</span><span>${allAssess.length} assessed</span>`)}</div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title"><h2>Attendance overview</h2></div><p class="panel-subtitle">Recorded classroom attendance across your workspace</p></div><div class="segmented">${[7,14].map(n=>`<button data-action="chart-days" data-days="${n}" class="${ctx.chartDays===n?'active':''}">${n} days</button>`).join('')}</div></div><div class="chart-topline"><div class="chart-total"><strong>${attendanceStats(d.daily_attendance).rate===null?'&mdash;':fmt(attendanceStats(d.daily_attendance).rate,1)+'%'}</strong><span>recorded attendance</span></div><div class="inline-legend"><span><i></i>Present</span><span><i style="background:var(--amber)"></i>Absent</span></div></div>${lineChart(trend(d,ctx.chartDays))}<div class="panel-foot"><span>${icon('info',11)} Rate excludes tour, off and unrecorded days.</span><button class="text-link" data-action="nav" data-route="analytics">View analytics ${icon('arrow',12)}</button></div></section><section class="panel"><div class="panel-head" style="padding-bottom:8px"><div class="panel-title"><h2>On the learning floor</h2><small>${active.length} active</small></div><button class="text-link" data-action="nav" data-route="batches">View all ${icon('arrow',12)}</button></div>${active.length?active.slice(0,3).map(b=>batchMini(ctx,b,d)).join(''):empty('No active batches','Move a planning batch to Active to begin.')}<div class="panel-foot"><span>${d.attendance_10day.filter(r=>checklist(r.days).status==='Complete').length} checklists complete</span><span class="green-text">Keep the momentum</span></div></section></div>
 <div class="dashboard-lower"><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Assessment outcomes</h2></div>${icon('award',16)}</div>${donut(outcomeItems(allAssess))}</section><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Companies at a glance</h2></div><button class="text-link" data-action="nav" data-route="companies">${icon('arrow',14)}</button></div><div class="panel-body" style="padding-top:12px">${companies.filter(c=>c.trainees).slice(0,4).map((c,i)=>`<div class="company-rank"><span class="rank-number">0${i+1}</span>${companyLogo(c.name)}<div><strong>${e(c.name)}</strong>${progress(c.trainees,companies[0]?.trainees||1,i===0?'red':'blue')}</div><span>${c.trainees}</span></div>`).join('')||empty('No enrolled companies','Enroll a trainee to begin.')}</div></section><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Latest check-ins</h2></div><span class="live-dot ${''}"></span></div><div class="activity-list">${recent.map(r=>{const t=d.trainees.find(t=>t.id===r.trainee_id);return `<div class="activity-item"><span class="activity-icon">${icon(wasLate(r.arrival_time)?'clock':'check',13)}</span><div><p><strong>${e(t?.trainee_name||'Trainee')}</strong><br>${e(batch(ctx,r.batch_id)?.batch_name||'')} &middot; ${e(r.status)}</p><small>${dateLabel(r.date)} at ${cairoTime(r.arrival_time)} ${wasLate(r.arrival_time)?'&middot; '+minutesLate(r.arrival_time)+'m after start':''}</small></div></div>`;}).join('')||empty('No check-ins yet','Your first arrival will appear here.')}</div><div class="panel-foot"><span>${'From saved attendance records'}</span></div></section></div>`;
}
export function batches(ctx){const d=scoped(ctx),write=ctx.store.canWrite();if(ctx.detailId){const b=d.batches.find(b=>b.id===ctx.detailId)||ctx.store.data.batches.find(b=>b.id===ctx.detailId);if(b)return batchDetail(ctx,b);ctx.detailId='';}
 const controls=`<div class="segmented">${[['board','board','Board'],['list','list','List'],['timeline','timeline','Timeline'],['calendar','calendar','Calendar']].map(([m,ico,label])=>`<button data-action="batch-view" data-view="${m}" class="${ctx.batchView===m?'active':''}" aria-pressed="${ctx.batchView===m}">${icon(ico,13)}${label}</button>`).join('')}</div>`;
 let content='';
 if(ctx.batchView==='board')content=`<div class="kanban">${[...BATCH_STATUSES,...(d.batches.some(b=>!b.status)?['Not recorded']:[])].map(status=>`<section class="kanban-column" data-drop-status="${status}"><div class="kanban-head"><div>${badge(status)}<span class="kanban-count">${d.batches.filter(b=>(b.status||'Not recorded')===status).length}</span></div>${write&&status!=='Not recorded'?iconBtn('plus','new-batch','Add '+status.toLowerCase()+' batch',`data-status="${status}"`):''}</div>${d.batches.filter(b=>(b.status||'Not recorded')===status).map(b=>{const bs=batchStats(d,b.id),trainees=d.trainees.filter(t=>t.batch_id===b.id);return `<article class="batch-card" draggable="${write}" data-batch-drag="${b.id}"><div class="card-top"><span class="batch-mini-symbol">${icon('cap',19)}</span>${write?iconBtn('more','edit-batch','Edit '+b.batch_name,`data-id="${b.id}"`):''}</div><h3><button class="text-link" style="font-size:21px;color:var(--text);font-weight:550" data-action="batch-detail" data-id="${b.id}">${e(b.batch_name)}</button></h3><div class="card-meta">${icon('calendar',12)}${dateLabel(b.start_date)} - ${dateLabel(b.end_date)}</div><p>${e(b.description||'Training batch details pending.')}</p><div class="card-roster"><div class="avatar-stack">${trainees.slice(0,4).map(t=>avatar(t.trainee_name,true)).join('')}${trainees.length>4?`<span class="avatar-count">+${trainees.length-4}</span>`:''}</div><span>${trainees.length} enrolled</span></div><div style="display:flex;justify-content:space-between;font-size:9px;color:var(--faint);margin-bottom:9px"><span>Checklist completion</span><span>${bs.completion===null?'Not recorded':fmt(bs.completion)+'%'}</span></div>${progress(bs.completion,100,status==='Completed'?'green':'red')}<div class="batch-card-bottom"><span>${bs.assessed?fmt(bs.score,1)+'% avg. score':'Assessments pending'}</span><button class="text-link" data-action="batch-detail" data-id="${b.id}">Open batch ${icon('arrow',13)}</button></div></article>`;}).join('')||`<div class="empty" style="padding:35px 10px;width:100%"><p>Drag a batch here${write?' or create a new one.':'.'}</p></div>`}</section>`).join('')}</div>`;
 if(ctx.batchView==='list')content=`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Batch</th><th>Status</th><th>Schedule</th><th>Enrolled</th><th>Completion</th><th>Average score</th><th></th></tr></thead><tbody>${d.batches.map(b=>{const s=batchStats(d,b.id);return `<tr><td><button class="text-link" style="color:var(--text)" data-action="batch-detail" data-id="${b.id}">${e(b.batch_name)}</button></td><td>${badge(b.status)}</td><td>${dateLabel(b.start_date)} - ${dateLabel(b.end_date)}</td><td>${s.trainees}</td><td>${ring(s.completion,35)}</td><td>${s.score===null?'\u2014':fmt(s.score,1)+'%'}</td><td>${write?iconBtn('edit','edit-batch','Edit batch',`data-id="${b.id}"`):''}</td></tr>`;}).join('')}</tbody></table></div></section>`;
 if(ctx.batchView==='timeline'){const dates=d.batches.flatMap(b=>[b.start_date,b.end_date]).filter(Boolean).sort(),start=dates[0]||today(),end=dates.at(-1)||addDays(today(),30),days=Math.max(1,(Date.parse(end)-Date.parse(start))/86400000);content=`<section class="panel"><div class="panel-head"><div class="panel-title"><h2>Batch timeline</h2></div><span class="faint" style="font-size:10px">${dateLabel(start)} - ${dateLabel(end)}</span></div><div class="timeline-chart"><div class="timeline-axis">${[0,1,2,3,4].map(i=>`<span>${dateLabel(addDays(start,Math.round(days*i/4)))}</span>`).join('')}</div>${d.batches.filter(b=>b.start_date&&b.end_date).map(b=>`<div class="timeline-row"><span>${e(b.batch_name)}</span><div class="timeline-track"><button class="timeline-bar" data-action="batch-detail" data-id="${b.id}" style="left:${(Date.parse(b.start_date)-Date.parse(start))/86400000/days*100}%;width:${Math.max(1,(Date.parse(b.end_date)-Date.parse(b.start_date))/86400000/days*100)}%">${e(b.status)}</button></div></div>`).join('')}</div></section>`;}
 if(ctx.batchView==='timeline')content+=`<div class="notice subtle">${d.batches.filter(b=>!b.start_date||!b.end_date).length} batches have no complete date range. They remain in the board and list; no dates were invented. Imported ranges may represent observed dates rather than a planned schedule.</div>`;
 if(ctx.batchView==='calendar')content=calendarView(ctx,d);
 return heading('Batches','Manage company training cohorts.',write?btn('New batch','new-batch','primary','plus'):'','PROGRAM MANAGEMENT')+scopeBar(ctx)+`<div class="batch-view-bar">${controls}<p>${write?'Drag cards between stages, or edit their status.':'Browse the company training schedule.'}</p></div>`+content;
}
function calendarView(ctx,d){const first=ctx.calendarMonth+'-01',start=new Date(first+'T12:00:00Z').getUTCDay(),last=new Date(Number(ctx.calendarMonth.slice(0,4)),Number(ctx.calendarMonth.slice(5,7)),0).getDate();const cells=Array.from({length:Math.ceil((start+last)/7)*7},(_,i)=>{const day=i-start+1;if(day<1||day>last)return '<div class="calendar-cell"></div>';const date=`${ctx.calendarMonth}-${String(day).padStart(2,'0')}`,scheduled=d.batches.filter(b=>b.session_dates.includes(date));return `<div class="calendar-cell ${date===today()?'is-today':''}"><span>${day}</span>${scheduled.map(b=>`<button class="calendar-event" data-action="batch-detail" data-id="${b.id}" title="${e(b.batch_name)} - session ${b.session_dates.indexOf(date)+1}">${e(b.batch_name)} &middot; D${b.session_dates.indexOf(date)+1}</button>`).join('')}</div>`;}).join('');return `<section class="panel"><div class="toolbar"><h3>${dateLabel(first,{month:'long',year:'numeric'})}</h3><div class="toolbar-right">${iconBtn('chevron','prev-month','Previous month','style="transform:rotate(180deg)"')}${btn('Today','calendar-today','small')}${iconBtn('chevron','next-month','Next month')}</div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(day=>`<div class="calendar-weekday">${day}</div>`).join('')}${cells}</div></section>`;}
function batchDetail(ctx,b){const d=scoped({...ctx,batchId:b.id}),s=batchStats(d,b.id),trainees=d.trainees;const stats=attendanceStats(d.daily_attendance);return heading(b.batch_name,`${dateLabel(b.start_date,{month:'long',day:'numeric'})} - ${dateLabel(b.end_date,{month:'long',day:'numeric',year:'numeric'})}`,`${btn('All batches','back-batches','secondary','arrow')}${btn('Generate reports','batch-report','secondary','book',`data-id="${b.id}"`)}${ctx.store.canWrite()?btn('Edit batch','edit-batch','primary','edit',`data-id="${b.id}"`):''}`,'BATCH WORKSPACE')+`<div class="notice subtle">${sourceButton(b)}${badge(b.status)}<span>${e(b.description)}</span></div><div class="stats-grid">${stat('Enrolled',s.trainees,'users','Trainees in this batch')}${stat('Classroom attendance',stats.rate===null?'\u2014':fmt(stats.rate,1)+'%','calendar',`${stats.present} present / ${stats.present+stats.absent} recorded`)}${stat('Checklist completion',s.completion===null?'Not recorded':fmt(s.completion)+'%','checklist','Average of trainee checklists')}${stat('Assessment average',s.score===null?'\u2014':fmt(s.score,1)+'%','award',`${s.assessed} saved assessments`)}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title"><h2>${b.source_id?'Recorded attendance dates':'The 10-session journey'}</h2></div><p class="panel-subtitle">Each cell shows recorded presence, not checklist completion. An empty calendar means dates were not supplied.</p></div></div><div class="panel-body"><div class="session-strip" style="grid-template-columns:repeat(5,1fr);margin:0">${b.session_dates.map((date,i)=>{const ds=attendanceStats(d.daily_attendance.filter(a=>a.date===date));return `<button class="session-day ${date===today()?'active':''}" data-action="attendance-date" data-date="${date}" data-batch="${b.id}"><small>${b.source_id?'RECORD DATE':'SESSION '+(i+1)}</small><strong>${dateLabel(date)}</strong><span>${ds.present} present</span></button>`;}).join('')}</div></div><div class="panel-foot"><span>${stats.late} manual late flags</span><span>${stats.calculatedLate} calculated late arrivals</span></div></section><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Assessment distribution</h2></div></div>${donut(outcomeItems(assessedRows(d.assessments)))}</section></div><div class="batch-record-links">${btn('All attendance records ('+d.daily_attendance.length+')','batch-records','secondary','calendar',`data-kind="register" data-id="${b.id}"`)}${btn('All assessments ('+d.assessments.length+')','batch-records','secondary','award',`data-kind="assessments" data-id="${b.id}"`)}${btn('All checklist periods ('+d.attendance_10day.length+')','batch-records','secondary','checklist',`data-kind="summaries" data-id="${b.id}"`)}</div><section class="panel"><div class="toolbar"><h3>Trainee roster <span class="faint" style="font-size:11px;margin-left:8px">${trainees.length}</span></h3><div class="toolbar-right">${btn('Take attendance','attendance-for-batch','secondary','calendar',`data-id="${b.id}"`)}${ctx.store.canWrite()?btn('Enroll trainee','new-trainee','primary','plus',`data-batch="${b.id}"`):''}</div></div><div class="table-wrap"><table><thead><tr><th>Trainee</th><th>Company</th><th>Checklist</th><th>Attendance</th><th>Assessment</th><th></th></tr></thead><tbody>${trainees.map(t=>{const r=checklistFor(d,t.id),a=assessmentFor(d,t.id),ats=attendanceStats(d.daily_attendance.filter(r=>r.trainee_id===t.id));return `<tr><td>${person(ctx,t,'job')}</td><td>${e(company(ctx,t.company_id))}</td><td>${ring(r?checklist(r.days).percent:null,35)}</td><td>${ats.present} present &middot; ${ats.absent} absent</td><td>${a?badge(a.assessment_outcome):'<span class="faint">Not assessed</span>'}</td><td>${iconBtn('arrow','profile','View trainee',`data-id="${t.id}"`)}</td></tr>`;}).join('')||'<tr><td colspan="6">No trainees enrolled.</td></tr>'}</tbody></table></div></section>`;}
export function trainees(ctx){const d=scoped(ctx),rows=findTrainees(ctx,d),p=pageRows(ctx,rows),write=ctx.store.canWrite();return heading('Trainees','Manage the company trainee directory.',`${btn('Export directory','export','secondary','download')}${write?btn('Enroll trainee','new-trainee','primary','plus'):''}`,'PEOPLE DIRECTORY')+scopeBar(ctx)+`<section class="panel"><div class="toolbar"><div class="toolbar-left">${searchInput(ctx,'Search name, company or role...')}</div><div class="toolbar-right"><span class="faint" style="font-size:10px">${rows.length} trainees</span><select data-field="sort" aria-label="Sort trainees">${option('name','Sort: name',ctx.sort)}${option('company','Sort: company',ctx.sort)}</select></div></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Trainee</th><th>Company</th><th>Batch</th><th>Attendance</th><th>Checklist</th><th>Assessment</th><th>Actions</th></tr></thead><tbody>${p.rows.map(t=>{const a=assessmentFor(d,t.id),r=checklistFor(d,t.id),at=attendanceStats(d.daily_attendance.filter(r=>r.trainee_id===t.id));return `<tr><td>${person(ctx,t,'job')}</td><td>${e(company(ctx,t.company_id))}</td><td><button class="text-link" data-action="batch-detail" data-id="${t.batch_id}">${e(batch(ctx,t.batch_id)?.batch_name)}</button></td><td><span class="green-text">${at.present} present</span><small>${at.absent} absent &middot; ${at.late} late flags</small></td><td>${ring(r?checklist(r.days).percent:null,35)}</td><td>${a?badge(a.assessment_outcome):'<span class="faint">Not assessed</span>'}</td><td><div class="row-actions">${iconBtn('arrow','profile','Open trainee profile',`data-id="${t.id}"`)}${write?iconBtn('edit','edit-trainee','Edit trainee',`data-id="${t.id}"`):''}</div></td></tr>`;}).join('')}</tbody></table></div>${pagination(ctx,p)}`:empty('No trainees found','Try a different search or enroll someone new.',write?btn('Enroll trainee','new-trainee','primary','plus'):'')}</section>`;}
export function attendance(ctx){const d=scoped(ctx),b=batch(ctx,ctx.batchId);if(!b)return heading('Daily attendance','A clear record of every training day.',ctx.store.canWrite()?btn('Create a batch','new-batch','primary','plus'):'')+empty('Create your first batch','Add a batch and enroll trainees before taking attendance.');const all=findTrainees(ctx,d),records=d.daily_attendance.filter(r=>r.date===ctx.date),ats=attendanceStats(records),unrecorded=d.trainees.filter(t=>!records.some(r=>r.trainee_id===t.id&&r.status)).length,rows=all.filter(t=>!ctx.attendanceStatus||(records.find(r=>r.trainee_id===t.id)?.status||'Unrecorded')===ctx.attendanceStatus),p=pageRows(ctx,rows),valid=!!b.source_id||b.session_dates.includes(ctx.date),write=ctx.store.canWrite()&&valid,selected=ctx.selection.size;
 return heading('Daily attendance','Show up. Check in. Make progress.',`${btn('All saved records','nav','secondary','list','data-route="register"')}${btn('Export register','export','secondary','download')}`, 'ATTENDANCE & COMMITMENT')+scopeBar(ctx,{requiredBatch:true})+`<div class="session-strip">${b.session_dates.map((date,i)=>{const entries=d.daily_attendance.filter(r=>r.date===date);return `<button class="session-day ${date===ctx.date?'active':''}" data-action="set-date" data-date="${date}"><small>${b.source_id?'RECORD DATE':'DAY '+String(i+1).padStart(2,'0')}</small><strong>${dateLabel(date)}</strong><span>${attendanceStats(entries).present} present</span></button>`;}).join('')}</div><div class="stats-grid">${stat('Present',ats.present,'check','Recorded present, including late arrivals')}${stat('Absent',ats.absent,'users','Only explicitly marked absences')}${stat('After 11:00 AM',ats.calculatedLate,'clock',`${ats.late} entries manually flagged late`)}${stat('Unrecorded',Math.max(0,unrecorded),'calendar',`${ats.tour} tour days / ${ats.off} off days`)}</div>${!valid?'<div class="notice">'+icon('info',16)+'This date is not in the batch schedule. Choose a scheduled date above.</div>':''}<section class="panel"><div class="toolbar"><div class="toolbar-left">${searchInput(ctx)}</div><div class="toolbar-right"><select data-field="attendanceStatus" aria-label="Filter attendance status">${option('','All statuses',ctx.attendanceStatus)}${[...STATUSES,'Unrecorded'].map(s=>option(s,s,ctx.attendanceStatus)).join('')}</select><input type="date" aria-label="Attendance date" data-field="date" value="${ctx.date}"></div></div>${selected&&write?`<div class="selection-bar"><strong>${selected} selected</strong><select id="bulk-status" aria-label="Bulk attendance status">${STATUSES.map(s=>option(s,s,ctx.bulkStatus)).join('')}</select>${btn('Apply to selected','bulk-attendance','small','check')}<span class="faint">No arrival time is invented.</span><button class="text-link" data-action="clear-selection">Clear</button></div>`:''}${rows.length?`<div class="table-wrap"><table><thead><tr><th style="width:35px;padding-right:0"><input type="checkbox" aria-label="Select all trainees on this page" data-select-all ${p.rows.every(t=>ctx.selection.has(t.id))&&p.rows.length?'checked':''} ${!write?'disabled':''}></th><th>Trainee</th><th>Arrival</th><th>Departure</th><th>Status</th><th title="Manually checked late flag, independent of calculated lateness">Late flag</th><th>Minutes late</th><th>Actions</th></tr></thead><tbody>${p.rows.map(t=>{const r=records.find(r=>r.trainee_id===t.id),late=wasLate(r?.arrival_time);return `<tr class="${late?'late-row':''}"><td style="padding-right:0"><input type="checkbox" data-select="${t.id}" aria-label="Select ${e(t.trainee_name)}" ${ctx.selection.has(t.id)?'checked':''} ${!write?'disabled':''}></td><td>${person(ctx,t)}</td><td class="mono">${r?.arrival_time?cairoTime(r.arrival_time):'\u2014'}</td><td class="mono">${r?.departure_time?cairoTime(r.departure_time):'\u2014'}</td><td>${badge(r?.status||'Unrecorded')}</td><td><input type="checkbox" data-late="${t.id}" aria-label="Manual late flag for ${e(t.trainee_name)}" ${r?.is_late?'checked':''} ${!write||!r||['Absent','Off Day'].includes(r.status)?'disabled':''}></td><td>${late?`<span class="late-minutes">${minutesLate(r.arrival_time)} min</span>`:'<span class="faint">0</span>'}</td><td><div class="row-actions">${write?(!r?.arrival_time?btn('Check in','check-in','small','plus',`data-id="${t.id}"`):!r.departure_time?btn('Check out','check-out','small','logout',`data-id="${t.id}"`):'<span class="faint" style="font-size:9px">Recorded</span>'):'<span class="faint">Read only</span>'}${write?iconBtn('edit','edit-attendance','Edit attendance for '+t.trainee_name,`data-id="${t.id}"`):''}</div></td></tr>`;}).join('')}</tbody></table></div>${pagination(ctx,p)}`:empty('No matching trainees','Change the company or status filter to see more people.')}<div class="panel-foot"><span>${icon('info',11)} Late flags are manual. Minutes late are calculated from Cairo arrival time.</span><span>11:00 AM start</span></div></section>`;
}
function checkboxGrid(ctx,r){const b=batch(ctx,r.batch_id);return `<div class="day-checks">${r.days.map((on,i)=>`<label class="day-check" title="Session ${i+1}: ${b?.session_dates[i]||''}"><input type="checkbox" data-checklist="${r.id}" data-day="${i}" aria-label="${e(ctx.store.data.trainees.find(t=>t.id===r.trainee_id)?.trainee_name)} day ${i+1} completion" ${on?'checked':''} ${!ctx.store.canWrite()?'disabled':''}><span>${on?icon('check',13):i+1}</span></label>`).join('')}</div>`;}
export function summaries(ctx){return checklistRegister(ctx,{scoped,heading,scopeBar,pageRows,pagination,searchInput,person,company,batch,checkboxGrid});}
export function assessments(ctx){return assessmentRegister(ctx,{scoped,heading,scopeBar,pageRows,pagination,searchInput,person,company,batch});}
export function companies(ctx){const d=scoped(ctx),all=companyStats(ctx,d).sort((a,b)=>ctx.companySort==='score'?(b.average??-1)-(a.average??-1):b.trainees-a.trainees||a.name.localeCompare(b.name)),rows=all.filter(c=>c.name.toLowerCase().includes(ctx.search.toLowerCase())),p=pageRows(ctx,rows,12),represented=all.filter(c=>c.trainees).length;return heading('Companies','Manage organizations represented in company training.',ctx.store.canWrite()?btn('Add company','new-company','primary','plus'):'','COMPANY DIRECTORY')+scopeBar(ctx)+`<div class="stats-grid">${stat('Directory companies',ctx.store.data.companies.length,'building','The complete organization directory')}${stat('Represented in scope',represented,'users',`${d.trainees.length} enrolled trainees`)}${stat('Assessments in scope',d.assessments.length,'award','Saved performance records')}${stat('Leading by score',all.filter(c=>c.assessed).sort((a,b)=>b.average-a.average)[0]?.name||'\u2014','chart','Based on assessed trainees, not headcount')}</div><div class="batch-view-bar"><div class="toolbar-left">${searchInput(ctx,'Search companies...')}</div><select data-field="companySort" aria-label="Rank companies" style="font-size:11px">${option('headcount','Rank by trainees',ctx.companySort)}${option('score','Rank by average score',ctx.companySort)}</select></div><div class="company-grid">${p.rows.map(c=>`<article class="company-card"><div class="company-card-top">${companyLogo(c.name)}<div><h3>${e(c.name)}</h3><small>${c.assessed} assessed ${c.assessed===1?'trainee':'trainees'}</small></div>${ctx.store.canWrite()?iconBtn('edit','edit-company','Edit '+c.name,`data-id="${c.id}"`):''}</div><div class="company-card-stats"><div><strong>${c.trainees}</strong><small>TRAINEES</small></div><div><strong>${c.average===null?'\u2014':fmt(c.average,1)+'%'}</strong><small>AVG. SCORE</small></div><div><strong>${c.batches}</strong><small>BATCHES</small></div></div><button class="text-link" data-action="company-trainees" data-id="${c.id}">Explore company ${icon('arrow',13)}</button></article>`).join('')}</div>${!rows.length?empty('No matching companies','Try another company name.'):pagination(ctx,p)}`;}
export function analytics(ctx){const d=scoped(ctx),ats=attendanceStats(d.daily_attendance),all=assessedRows(d.assessments),pass=all.filter(a=>scores(a).overall>=50).length,companies=companyStats(ctx,d).filter(c=>c.assessed).sort((a,b)=>b.average-a.average).slice(0,6),totalLateMinutes=d.daily_attendance.reduce((s,a)=>s+minutesLate(a.arrival_time),0);const highLate=d.daily_attendance.filter(a=>wasLate(a.arrival_time)).length;const avgCompletion=d.attendance_10day.length?d.attendance_10day.reduce((s,r)=>s+checklist(r.days).percent,0)/d.attendance_10day.length:null;
 return heading('Analytics & reports','Review operational performance and trends.',btn('Export report','export','primary','download'),'REPORTING')+scopeBar(ctx)+`<div class="stats-grid">${stat('Recorded attendance',ats.rate===null?'\u2014':fmt(ats.rate,1)+'%','calendar',`${ats.present} present of ${ats.present+ats.absent} classroom records`)}${stat('At or above 50%',all.length?fmt(pass/all.length*100,1)+'%':'\u2014','award',`${pass} of ${all.length} saved assessments`)}${stat('Checklist completion',avgCompletion===null?'Not recorded':fmt(avgCompletion,1)+'%','checklist','Average across 10-session checklists')}${stat('Average minutes late',highLate?fmt(totalLateMinutes/highLate,1):'\u2014','clock',`${highLate} calculated late arrivals only`)}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title"><h2>Daily attendance trend</h2></div><p class="panel-subtitle">Last 14 calendar days. Blank days have zero recorded entries.</p></div></div><div class="chart-topline"><div class="inline-legend"><span><i></i>Present</span><span><i style="background:var(--amber)"></i>Absent</span><span><i style="background:var(--blue)"></i>Late arrivals</span></div></div>${lineChart(trend(d,14),{height:235,series:[{key:'present',name:'Present',color:'var(--red)'},{key:'absent',name:'Absent',color:'var(--amber)'},{key:'calculatedLate',name:'Calculated late',color:'var(--blue)'}]})}<div class="panel-foot"><span>Tour and off-day records are excluded from the attendance rate.</span></div></section><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Assessment outcomes</h2></div></div>${donut(outcomeItems(all))}<div class="panel-foot"><span>Outcomes may be adjusted by an instructor.</span></div></section></div><div class="dashboard-grid" style="grid-template-columns:1fr 1fr"><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Batch performance</h2></div><span class="faint" style="font-size:9px">Average overall score</span></div><div class="bar-comparison">${d.batches.map(b=>{const bs=batchStats(d,b.id);return `<div class="bar-row"><span>${e(b.batch_name)}<small style="display:block;font-size:8px;color:var(--faint);margin-top:5px">${bs.assessed} assessed</small></span>${progress(bs.score||0,100,'red')}<b>${bs.score===null?'\u2014':fmt(bs.score,1)+'%'}</b></div>`;}).join('')}</div></section><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Company performance</h2></div><span class="faint" style="font-size:9px">Assessed trainees only</span></div><div class="bar-comparison">${companies.map(c=>`<div class="bar-row"><span>${e(c.name)}<small style="display:block;font-size:8px;color:var(--faint);margin-top:5px">n = ${c.assessed}</small></span>${progress(c.average||0,100,'blue')}<b>${fmt(c.average,1)}%</b></div>`).join('')||empty('No scores yet','Save assessments to compare companies.')}</div></section></div><section class="panel"><div class="panel-head"><div><div class="panel-title"><h2>Late arrival patterns</h2></div><p class="panel-subtitle">Calculated late arrivals by weekday and Cairo hour. All saved dates in scope.</p></div></div><div class="heatmap"><div class="heatmap-row labels"><span>Cairo time</span>${['11:00-11:59','12:00-12:59','13:00-13:59','14:00+'].map(h=>`<div class="heatmap-cell">${h}</div>`).join('')}</div>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((day,di)=>`<div class="heatmap-row"><span>${day}</span>${[11,12,13,14].map(hour=>{const count=d.daily_attendance.filter(r=>r.arrival_time&&wasLate(r.arrival_time)&&new Date(r.date+'T12:00:00Z').getUTCDay()===di&&(hour===14?Number(cairoTime(r.arrival_time).slice(0,2))>=14:Number(cairoTime(r.arrival_time).slice(0,2))===hour)).length;return `<div class="heatmap-cell" style="--heat:${count?Math.min(85,20+count*3):0}" title="${day}, ${hour===14?'14:00 or later':hour+':00 hour'}: ${count} late arrivals">${count||'\u2014'}</div>`;}).join('')}</div>`).join('')}</div><div class="insight-card"><h3>${icon('info',15)} Reading these numbers</h3><p>Counts reflect recorded entries, not scheduled headcount. Checklist completion is a separate activity measure. Company averages include only assessed trainees; small samples should not be treated as a reliable company ranking. Open a trainee profile for a skill-by-skill comparison with the batch average.</p></div></section>`;
}
export function settings(ctx){const s=ctx.store;return heading('Workspace settings','Manage internal access and system settings.','','INTERNAL SYSTEM')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><div class="panel-title"><h2>Internal company workspace</h2></div>${icon('shield',19)}</div><div class="panel-body"><div class="connection-card">${icon('lock',29)}<div><strong>Invitation-only access</strong><p>Only accounts authorized by your company administrator can sign in.</p></div></div><div class="setting-row"><div><strong>Persistent storage</strong><p>Training records are saved in the company server database, not browser storage.</p></div>${badge('Active')}</div><div class="setting-row"><div><strong>Live synchronization</strong><p>${s.connectionLost?'Connection interrupted. Reconnect to load the latest changes.':'Saved changes are shared with other signed-in team members.'}</p></div><span class="live-dot"></span></div><div class="setting-row"><div><strong>AI-assisted reports</strong><p>${s.aiEnabled?'Available with explicit consent and instructor review.':'Off. Built-in reports work without sending metrics to an external provider.'}</p></div>${badge(s.aiEnabled?'Active':'Not Started')}</div></div></section>
 <section class="panel"><div class="panel-head"><div class="panel-title"><h2>Your account</h2></div>${icon('users',17)}</div><div class="panel-body"><div class="setting-row"><div><strong>${e(s.user.full_name)}</strong><p>${e(s.user.email)}</p></div><span class="badge blue">${e(s.user.role)}</span></div><div class="setting-row"><div><strong>Your password</strong><p>Choose a private password. Changing it signs out every existing session.</p></div>${btn('Change password','change-password','secondary','lock')}</div><div class="setting-row"><div><strong>End this session</strong><p>Clears the workspace from this browser and signs out open internal tabs.</p></div>${btn('Sign out','logout','secondary','logout')}</div></div></section>
 <section class="panel"><div class="panel-head"><div class="panel-title"><h2>System preferences</h2></div>${icon('settings',17)}</div><div class="panel-body"><div class="setting-row"><div><strong>Appearance</strong><p>Dark by default, light when you prefer.</p></div>${btn(document.body.classList.contains('light')?'Dark mode':'Light mode','theme','secondary','sun')}</div><div class="setting-row"><div><strong>System timezone</strong><p>Cairo time, including daylight-saving changes.</p></div><span class="mono">Africa/Cairo</span></div><div class="setting-row"><div><strong>Late arrival threshold</strong><p>Strictly after 11:00 AM. Whole minutes rounded down.</p></div><span class="mono">11:00 AM</span></div></div></section>
 <section class="panel"><div class="panel-head"><div class="panel-title"><h2>Team & accountability</h2></div>${icon('lock',17)}</div><div class="panel-body"><div class="setting-row"><div><strong>Team access</strong><p>Invite company staff, assign roles, revoke invitations, or deactivate accounts.</p></div>${btn('Manage team','users','secondary','users',s.user.role!=='admin'?'disabled':'')}</div><div class="setting-row"><div><strong>Activity log</strong><p>Review changes, membership activity, and sign-ins.</p></div>${btn('View activity','activity','secondary','clock',s.user.role!=='admin'?'disabled':'')}</div><div class="setting-row"><div><strong>Exports & backup</strong><p>Export reports here. Your server owner should also back up the full database.</p></div>${btn('Export','export','secondary','download',!s.canWrite()?'disabled':'')}</div><div class="setting-row"><div><strong>Operating guide</strong><p>From the first batch to the final assessment.</p></div>${btn('Open guide','help','secondary','book')}</div></div></section></div>`;}

export function shell(ctx){const s=ctx.store,name=NAV.find(n=>n[0]===ctx.route)?.[1]||'Workspace settings',active=s.data.batches.filter(b=>b.status==='Active').length;const nav=(keys)=>NAV.filter(n=>keys.includes(n[0])).map(([key,label,ico])=>`<a class="nav-link ${ctx.route===key?'active':''}" href="#/${key}" ${ctx.route===key?'aria-current="page"':''}>${icon(ico,17)}<span>${label}</span>${key==='batches'?`<small>${active}</small>`:key==='trainees'?`<small>${s.data.trainees.length}</small>`:''}</a>`).join('');const view={dashboard,batches,trainees,attendance,summaries,assessments,companies,analytics,settings,migration:()=>migrationView(ctx,{heading,scopeBar}),register:()=>registerView(ctx,{scoped,heading,scopeBar,pageRows,pagination,searchInput,person,batch})}[ctx.route]||dashboard;
 return `<div class="app-shell"><aside class="sidebar ${ctx.sidebarOpen?'is-open':''}" aria-label="Main navigation"><a class="brand" href="#/dashboard"><span class="brand-mark" aria-hidden="true"></span><span class="brand-word"><strong>INTERNAL</strong><small>Training</small></span></a><button class="workspace-switch" data-action="${'nav'}" data-route="settings"><span class="workspace-symbol">${icon('building',16)}</span><div><strong>Internal workspace</strong><small>${'Company training records'}</small></div>${icon('down',12)}</button><div class="nav-section"><div class="nav-caption">Workspace</div>${nav(['dashboard'])}</div><div class="nav-section"><div class="nav-caption">Management</div>${nav(['batches','trainees','attendance','summaries','assessments'])}</div><div class="nav-section"><div class="nav-caption">Intelligence</div>${nav(['companies','analytics','register','migration'])}</div><div class="sidebar-spacer"></div><a class="nav-link ${ctx.route==='settings'?'active':''}" href="#/settings">${icon('settings',17)}<span>Workspace settings</span></a><button class="nav-link" data-action="help" style="background:none;border:none;width:100%;text-align:left">${icon('help',17)}<span>Help & getting started</span></button><div class="sidebar-note"><small>INTERNAL COMPANY SYSTEM</small><p>Company records.<br>Controlled access.</p><button data-action="nav" data-route="analytics">Open reports ${icon('arrow',12)}</button></div><div class="sidebar-user">${avatar(s.user.full_name)}<div><strong>${e(s.user.full_name)}</strong><small>${s.user.role[0].toUpperCase()+s.user.role.slice(1)}</small></div>${iconBtn('more','nav','Workspace settings','data-route="settings"')}</div></aside><div class="main-wrap"><header class="topbar">${iconBtn('menu','toggle-sidebar','Toggle navigation','data-mobile-toggle')}<div class="breadcrumbs">${icon('grid',14)}<span>Internal</span><span>/</span><b>${name}</b></div><div class="topbar-right"><button class="portal-back-button" type="button" data-action="back-portal">${icon('back',15)}<span>Portal</span></button><button class="command-button" data-action="command">${icon('search',14)}Search anything <kbd>Ctrl K</kbd></button><span class="live-status"><i class="live-dot ${''}"></i>${s.connectionLost?'Reconnecting':'Internal workspace'}</span><span class="top-divider"></span>${iconBtn(document.body.classList.contains('light')?'moon':'sun','theme','Toggle light or dark mode')}${iconBtn('bell','activity','View workspace activity')}${avatar(s.user.full_name)}</div></header>${!navigator.onLine||s.connectionLost?`<div class="offline-banner">${'Connection interrupted. This view may be out of date. Reconnect before editing.'}</div>`:''}<main id="main" class="content" tabindex="-1">${view(ctx)}<footer class="footer"><span>${'Internal company training system'} &nbsp; / &nbsp; Africa/Cairo</span><span>INTERNAL OPERATIONS</span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${[['dashboard','Home','grid'],['batches','Batches','cap'],['attendance','Attendance','calendar'],['assessments','Assess','award'],['settings','More','menu']].map(([key,label,ico])=>`<a href="#/${key}" class="${ctx.route===key?'active':''}" ${ctx.route===key?'aria-current="page"':''}>${icon(ico,19)}<span>${label}</span></a>`).join('')}</nav></div>`;
}
export function authView(ctx){
 const setup=ctx.store.setupRequired,join=!setup&&ctx.route==='join',unavailable=ctx.store.status==='unavailable';
 const mode=setup?'setup':join?'join':'login';
 const title=unavailable?'Connection needed.':setup?'Make it yours.':join?'Welcome to the company workspace.':'Welcome back.';
 return `<div class="auth-layout"><section class="auth-brand"><div class="brand"><span class="brand-mark" aria-hidden="true"></span><span class="brand-word"><strong>INTERNAL</strong><small>Training</small></span></div><div class="auth-story"><span class="eyebrow">INTERNAL COMPANY SYSTEM</span><h1>Company training.<br>Clear records.<br>Controlled access.</h1><p>One internal workspace for attendance, rosters and assessments.<br>Access is limited to authorized staff.</p><div class="private-brand-tag">${icon('shield',16)} COMPANY ACCESS ONLY</div></div><div class="auth-brand-footer"><span>INTERNAL TRAINING</span><span>COMPANY USE ONLY</span></div></section><section class="auth-form-side"><div class="auth-form" id="main" tabindex="-1"><span class="auth-private-label">${icon('lock',13)} INTERNAL SYSTEM</span><h2>${title}</h2>${unavailable?`<p>We could not verify your connection to the internal system. Your workspace stays locked.</p><div class="notice danger">${e(ctx.store.error||'Check the server and try again.')}</div><button class="btn primary" data-action="retry-connection">Try again ${icon('refresh',16)}</button>`:`<p>${setup?'Create the first company administrator account. Use the one-time setup code printed in the server terminal.':join?'Your administrator has assigned your account and access level. Choose a password only you know.':'Sign in to the company training system.<br>Authorized staff only.'}</p><form id="auth-form" data-mode="${mode}">
 ${setup||join?`<label class="field" for="token"><span>${setup?'One-time setup code':'Invitation code'}</span><input id="token" name="token" type="password" required minlength="43" maxlength="43" autocomplete="off" spellcheck="false" value="${e(join?ctx.invitationToken||'':'')}" placeholder="${setup?'From your server terminal':'From your company invitation'}"></label>`:''}
 ${setup?'<label class="field" for="full_name"><span>Your full name</span><input id="full_name" name="full_name" autocomplete="name" required maxlength="160" placeholder="Your full name"></label>':''}
 ${!join?`<label class="field" for="email"><span>Work email</span><input id="email" name="email" type="email" autocomplete="username" required maxlength="254" placeholder="Your work email" value="${e(ctx.loginEmail||'')}"></label>`:''}
 <label class="field" for="password"><span>${setup||join?'Choose a password':'Password'}</span><input id="password" name="password" type="password" autocomplete="${setup||join?'new-password':'current-password'}" required ${setup||join?'minlength="12"':''} maxlength="256" placeholder="${setup||join?'At least 12 characters':'Your password'}"></label>
 ${setup||join?'<label class="field" for="confirm_password"><span>Confirm password</span><input id="confirm_password" name="confirm_password" type="password" autocomplete="new-password" required minlength="12" maxlength="256" placeholder="Enter your password again"></label>':''}
 <div id="auth-error" role="alert"></div><button class="btn primary" type="submit">${setup?'Create internal workspace':join?'Activate my account':'Sign in to internal system'} ${icon('arrow',16)}</button></form>`}
 <div class="auth-access-note">${icon('shield',16)}<p>${setup?'The setup code works once. Your historical company records are already loaded. No default users or shared passwords are included.':'Access is restricted to invited staff members. For access or account recovery, contact your company administrator.'}</p></div>
 ${join?'<button class="text-link" data-action="login">Already activated? Sign in</button>':''}
 <div class="auth-bottom">Internal training system &middot; Company use only</div></div></section></div>`;
}

export function gettingStarted(ctx){
 const s=ctx.store,d=s.data,write=s.canWrite();
 const steps=[{title:'Add your companies',copy:'Create only the company records your trainees need.',done:!!d.companies.length,action:'new-company',label:'Add company',ico:'building'},{title:'Plan the first batch',copy:'Set the dates, capacity, and ten training sessions.',done:!!d.batches.length,action:'new-batch',label:'Create batch',ico:'cap'},{title:'Build your roster',copy:'Enroll your first trainee. Their checklist is created automatically.',done:!!d.trainees.length,action:'new-trainee',label:'Add trainee',ico:'users'}];
 return heading('Welcome to the internal training system.','Your company workspace is ready for its first records.',s.user.role==='admin'?btn('Invite staff','users','secondary','users'):'','SYSTEM SETUP')+`
 <section class="launch-hero"><div><span class="hero-tag">${icon('shield',14)} INTERNAL COMPANY SYSTEM</span><h2>Set up the company<br>training workspace.</h2><p>Add companies, create batches and invite authorized staff.</p><span class="private-launch-note">${icon('lock',13)} Company records &middot; Saved to the internal server</span></div><div class="launch-emblem" aria-hidden="true"><span>R</span><small>INTERNAL</small></div></section>
 <div class="stats-grid">${stat('Batches',d.batches.length,'cap','Your training programs')}${stat('Enrolled trainees',d.trainees.length,'users','Your trainee roster')}${stat('Attendance records',d.daily_attendance.length,'calendar','Recorded sessions only')}${stat('Saved assessments',d.assessments.length,'award','Measured performance')}</div>
 <section class="panel launch-panel"><div class="panel-head"><div><div class="panel-title"><h2>Your first steps</h2></div><p class="panel-subtitle">${write?'A clear start. Everything else follows.':'Your training team will add programs and trainees here.'}</p></div><span class="badge blue">${steps.filter(x=>x.done).length} of 3 complete</span></div><div class="launch-steps">${steps.map((step,i)=>`<article class="launch-step ${step.done?'is-done':''}"><span class="launch-step-number">${step.done?icon('check',19):'0'+(i+1)}</span><h3>${step.title}</h3><p>${step.copy}</p>${write?btn(step.done?'View '+(i===0?'companies':'batches'):step.label,step.done?'nav':step.action,step.done?'secondary':'primary',step.done?'arrow':step.ico,step.done?'data-route="'+(i===0?'companies':'batches')+'"':''):''}</article>`).join('')}</div></section>
 <div class="launch-bottom"><span>${icon('info',15)} Reports will appear as authorized staff add training records.</span>${btn('Read the operating guide','help','ghost','book')}</div>`;
}
